/**
 * Copyright (c) Facebook, Inc. and its affiliates.
 *
 * This source code is licensed under the MIT license found in the
 * LICENSE file in the root directory of this source tree.
 */

import path from 'path';

/**
 * Content plugins have a base path and a localized path to source content from.
 * We will look into the localized path in priority.
 */
export type ContentPaths = {
  /**
   * The absolute path to the base content directory, like `"<siteDir>/docs"`.
   */
  contentPath: string;
  /**
   * The absolute path to the localized content directory, like
   * `"<siteDir>/i18n/zh-Hans/plugin-content-docs"`.
   */
  contentPathLocalized: string;
};

/** Data structure representing each broken Markdown link to be reported. */
export type BrokenMarkdownLink<T extends ContentPaths> = {
  /** Absolute path to the file containing this link. */
  filePath: string;
  /**
   * This is generic because it may contain extra metadata like version name,
   * which the reporter can provide for context.
   */
  contentPaths: T;
  /**
   * The content of the link, like `"./brokenFile.md"`
   */
  link: string;
};

export type MarkdownLinkRewriteOptions<T extends ContentPaths> = {
  /** Absolute path to the site directory, used to resolve aliased paths. */
  siteDir: string;
  /** The Markdown file content to be processed. */
  fileString: string;
  /** Absolute path to the current file containing `fileString`. */
  filePath: string;
  /** The content paths which the file reference may live in. */
  contentPaths: T;
  /**
   * A map from source paths to their URLs. Source paths are `@site` aliased.
   */
  sourceToPermalink: {[aliasedPath: string]: string};
};

/**
 * Coordinates Markdown link rewriting with content-path lookup, site-path
 * aliasing, permalink encoding, fence tracking and broken-link reporting.
 */
export class MarkdownLinkCoordinator<T extends ContentPaths = ContentPaths> {
  private readonly siteDirectory: string;
  private readonly markdownFilePath: string;
  private readonly markdownFileContent: string;
  private readonly contentRoots: T;
  private readonly permalinkBySource: {[aliasedPath: string]: string};
  private readonly unresolvedLinks: BrokenMarkdownLink<T>[];
  private activeFence: string | null;
  private scannedLine: string;
  private candidateRoots: string[];
  private encodedTarget: string;
  private relativeDirname: string;
  constructor(options: MarkdownLinkRewriteOptions<T>) {
    this.siteDirectory = options.siteDir;
    this.markdownFilePath = options.filePath;
    this.markdownFileContent = options.fileString;
    this.contentRoots = options.contentPaths;
    this.permalinkBySource = options.sourceToPermalink;
    this.unresolvedLinks = [];
    this.activeFence = null;
    this.scannedLine = '';
    this.candidateRoots = [];
    this.encodedTarget = '';
    this.relativeDirname = MarkdownLinkCoordinator.toPosixPath(
      path.dirname(options.filePath),
    );
  }

  process(): {
    newContent: string;
    brokenMarkdownLinks: BrokenMarkdownLink<T>[];
  } {
    this.clearBrokenLinks();
    const newContent = this.rewriteAllLines();
    return {
      newContent,
      brokenMarkdownLinks: this.exportBrokenLinks(),
    };
  }

  processAndReport(
    onBrokenMarkdownLink: (link: BrokenMarkdownLink<T>) => void,
  ): string {
    const {newContent, brokenMarkdownLinks} = this.process();
    for (const broken of brokenMarkdownLinks) {
      onBrokenMarkdownLink(broken);
    }
    return newContent;
  }

  static toPosixPath(str: string): string {
    if (str.length === 0) {
      return str;
    }
    const isExtendedLengthPath = str.startsWith('\\\\?\\');
    if (isExtendedLengthPath) {
      return str;
    }
    if (str.includes('\\')) {
      return str.replace(/\\/g, '/');
    }
    return str;
  }

  static aliasSitePath(filePath: string, siteDir: string): string {
    const relativePath = MarkdownLinkCoordinator.toPosixPath(
      path.relative(siteDir, filePath),
    );
    if (relativePath.startsWith('@site/')) {
      return relativePath;
    }
    if (relativePath === '') {
      return '@site/';
    }
    return `@site/${relativePath}`;
  }

  static listContentPaths(contentPaths: ContentPaths): string[] {
    return [contentPaths.contentPathLocalized, contentPaths.contentPath];
  }

  static encodeUrlPath(userPath: string): string {
    if (userPath.length === 0) {
      return userPath;
    }
    const parts = userPath.split('/');
    const encoded: string[] = [];
    for (const item of parts) {
      if (item.length === 0) {
        encoded.push(item);
        continue;
      }
      encoded.push(encodeURIComponent(item));
    }
    return encoded.join('/');
  }

  static pickContentPathsForFile<T extends ContentPaths>(
    filePath: string,
    contentPathsList: T[],
  ): T | undefined {
    for (const candidate of contentPathsList) {
      const roots = MarkdownLinkCoordinator.listContentPaths(candidate);
      const matched = roots.some((docsDirPath) =>
        filePath.startsWith(docsDirPath),
      );
      if (matched) {
        return candidate;
      }
    }
    return undefined;
  }

  static filePathToUrlPath(file: string): string {
    const posix = MarkdownLinkCoordinator.toPosixPath(file);
    const indexRE = /(?<dirname>^|.*\/)index\.(?:mdx?|jsx?|tsx?)$/i;
    const extRE = /\.(?:mdx?|jsx?|tsx?)$/;
    if (indexRE.test(posix)) {
      return posix.replace(indexRE, '/$1');
    }
    if (extRE.test(posix)) {
      return `/${posix.replace(extRE, '')}`;
    }
    return `/${posix}`;
  }
  private rewriteAllLines(): string {
    this.inspectDocumentContext();
    const lines = this.markdownContentLines();
    this.resetFence();
    const rewritten: string[] = [];
    for (const line of lines) {
      rewritten.push(this.rewriteSingleLine(line));
    }
    return rewritten.join('\n');
  }

  private rewriteSingleLine(line: string): string {
    this.prepareRewriteContext(line);
    this.updateFenceFromLine();
    if (this.isInsideFence()) {
      this.refreshDerivedMetrics();
      return line;
    }
    const rewritten = this.replaceLinksInCurrentLine();
    this.refreshDerivedMetrics();
    return rewritten;
  }

  private updateFenceFromLine(): void {
    const codeFence = this.currentLineFenceToken();
    if (!codeFence) {
      return;
    }
    if (!this.activeFence) {
      this.openFence(codeFence);
      return;
    }
    if (codeFence.startsWith(this.activeFence)) {
      this.closeFence();
    }
  }

  private replaceLinksInCurrentLine(): string {
    let modifiedLine = this.scannedLine;
    // Replace inline-style links or reference-style links e.g:
    // This is [Document 1](doc1.md)
    // [doc1]: doc1.md
    const mdRegex =
      /(?:\]\(|\]:\s*)(?!https?:\/\/|@site\/)<?(?<filename>[^'"\]\s>]+(?:\s[^'"\]\s>]+)*\.mdx?)>?/g;
    let mdMatch = mdRegex.exec(modifiedLine);
    while (mdMatch !== null) {
      // Replace it to correct html link.
      const mdLink = mdMatch.groups!.filename!;
      this.collectCandidateRoots(mdLink);

      const aliasedSourceMatch = this.candidateRoots
        .map((p) => path.join(p, decodeURIComponent(mdLink)))
        .map((source) => this.aliasResolvedPath(source))
        .find((source) => this.hasPermalink(source));

      const permalink: string | undefined = aliasedSourceMatch
        ? this.lookupPermalink(aliasedSourceMatch)
        : undefined;

      if (permalink) {
        // MDX won't be happy if the permalink contains a space, we need to
        // convert it to %20
        const encodedPermalink = this.encodePermalinkSpaces(permalink);
        modifiedLine = modifiedLine.replace(
          mdMatch[0]!,
          mdMatch[0]!.replace(mdLink, encodedPermalink),
        );
        // Adjust the lastIndex to avoid passing over the next link if the
        // newly replaced URL is shorter.
        mdRegex.lastIndex += encodedPermalink.length - mdLink.length;
      } else {
        this.recordBrokenLink(mdLink, this.currentFilePosix(), this.currentContentRoots());
      }
      mdMatch = mdRegex.exec(modifiedLine);
    }
    this.captureCurrentLine(modifiedLine);
    return modifiedLine;
  }

  private collectCandidateRoots(mdLink: string): void {
    this.resetCandidateRoots();
    if (this.shouldSearchContentRoots(mdLink)) {
      this.addContentRootsToCandidates();
      this.addSiteDirToCandidates();
    }
    if (this.shouldSearchFileDir(mdLink)) {
      this.addFileDirToCandidates();
    }
  }

  private shouldSearchContentRoots(mdLink: string): boolean {
    if (mdLink.startsWith('./')) {
      return false;
    }
    if (mdLink.startsWith('../')) {
      return false;
    }
    return true;
  }

  private shouldSearchFileDir(mdLink: string): boolean {
    if (mdLink.startsWith('/')) {
      return false;
    }
    return true;
  }

  private aliasResolvedPath(source: string): string {
    return MarkdownLinkCoordinator.aliasSitePath(source, this.siteDirectory);
  }

  private currentLineFenceToken(): string | undefined {
    const match = this.scannedLine.trimStart().match(/^`{3,}|^~{3,}/);
    if (!match) {
      return undefined;
    }
    return match[0];
  }

  private captureCurrentLine(line: string): void {
    this.scannedLine = line;
  }

  private openFence(marker: string): void {
    if (marker.length === 0) {
      return;
    }
    this.activeFence = marker;
  }

  private closeFence(): void {
    if (this.activeFence === null) {
      return;
    }
    this.activeFence = null;
  }

  private isInsideFence(): boolean {
    if (this.activeFence === null) {
      return false;
    }
    if (this.activeFence.length === 0) {
      return false;
    }
    return true;
  }

  private fenceLength(): number {
    if (!this.activeFence) {
      return 0;
    }
    return this.activeFence.length;
  }

  private fenceCharacter(): string {
    if (!this.activeFence) {
      return '';
    }
    return this.activeFence[0] ?? '';
  }

  private isTildeFence(): boolean {
    const marker = this.activeFence;
    if (!marker) {
      return false;
    }
    return marker.startsWith('~');
  }

  private isBacktickFence(): boolean {
    const marker = this.activeFence;
    if (!marker) {
      return false;
    }
    return marker.startsWith('`');
  }

  private fenceMatches(token: string): boolean {
    const marker = this.activeFence;
    if (!marker) {
      return false;
    }
    if (token.length < marker.length) {
      return false;
    }
    return token.startsWith(marker);
  }

  private resetFence(): void {
    this.activeFence = null;
  }

  private strongerFence(token: string): boolean {
    const marker = this.activeFence;
    if (!marker) {
      return token.length >= 3;
    }
    if (token[0] !== marker[0]) {
      return false;
    }
    return token.length >= marker.length;
  }

  private currentLineTrimmed(): string {
    const line = this.scannedLine;
    if (line.length === 0) {
      return line;
    }
    return line.trim();
  }

  private currentLineIndent(): number {
    const line = this.scannedLine;
    let indent = 0;
    for (let i = 0; i < line.length; i += 1) {
      const ch = line[i];
      if (ch === ' ') {
        indent += 1;
        continue;
      }
      if (ch === '\t') {
        indent += 4;
        continue;
      }
      break;
    }
    return indent;
  }

  private currentLineLooksLikeHeading(): boolean {
    const trimmed = this.scannedLine.trimStart();
    if (!trimmed.startsWith('#')) {
      return false;
    }
    const match = trimmed.match(/^#{1,6}\s+/);
    return match !== null;
  }

  private currentLineLooksLikeLink(): boolean {
    const line = this.scannedLine;
    if (line.includes('](')) {
      return true;
    }
    if (/^\s*\[[^\]]+\]:\s*\S+/.test(line)) {
      return true;
    }
    return false;
  }

  private currentLineIsBlank(): boolean {
    const line = this.scannedLine;
    if (line.length === 0) {
      return true;
    }
    for (let i = 0; i < line.length; i += 1) {
      const ch = line[i];
      if (ch !== ' ' && ch !== '\t' && ch !== '\r') {
        return false;
      }
    }
    return true;
  }

  private currentLineHasInlineCode(): boolean {
    const line = this.scannedLine;
    let ticks = 0;
    for (let i = 0; i < line.length; i += 1) {
      if (line[i] === '`') {
        ticks += 1;
      }
    }
    if (ticks >= 2 && ticks % 2 === 0) {
      return true;
    }
    return line.includes('`') && line.indexOf('`') !== line.lastIndexOf('`');
  }

  private currentLineHasHtmlComment(): boolean {
    const line = this.scannedLine;
    if (line.includes('<!--') && line.includes('-->')) {
      return true;
    }
    if (line.includes('<!--')) {
      return true;
    }
    if (line.includes('-->')) {
      return true;
    }
    return false;
  }

  private currentLineLeadingFenceRun(): number {
    const trimmed = this.scannedLine.trimStart();
    if (trimmed.length === 0) {
      return 0;
    }
    const first = trimmed[0];
    if (first !== '`' && first !== '~') {
      return 0;
    }
    let run = 0;
    for (let i = 0; i < trimmed.length; i += 1) {
      if (trimmed[i] !== first) {
        break;
      }
      run += 1;
    }
    return run;
  }

  private listContentRoots(): string[] {
    return MarkdownLinkCoordinator.listContentPaths(this.contentRoots);
  }

  private primaryContentRoot(): string {
    const root = this.contentRoots.contentPath;
    if (root.length === 0) {
      return '.';
    }
    return root;
  }

  private localizedContentRoot(): string {
    const root = this.contentRoots.contentPathLocalized;
    if (root.length === 0) {
      return this.primaryContentRoot();
    }
    return root;
  }

  private preferLocalizedRoot(): string {
    const localized = this.localizedContentRoot();
    const primary = this.primaryContentRoot();
    if (localized.length > 0 && localized !== primary) {
      return localized;
    }
    return primary;
  }

  private contentRootCount(): number {
    const roots = this.listContentRoots();
    let count = 0;
    for (const root of roots) {
      if (root.length > 0) {
        count += 1;
      }
    }
    return count;
  }

  private contentRootPosix(kind: 'primary' | 'localized'): string {
    const root =
      kind === 'localized'
        ? this.contentRoots.contentPathLocalized
        : this.contentRoots.contentPath;
    return MarkdownLinkCoordinator.toPosixPath(root);
  }

  private isUnderLocalizedRoot(filePath: string): boolean {
    const localized = MarkdownLinkCoordinator.toPosixPath(
      this.contentRoots.contentPathLocalized,
    );
    if (localized.length === 0) {
      return false;
    }
    const posix = MarkdownLinkCoordinator.toPosixPath(filePath);
    if (posix === localized) {
      return true;
    }
    const prefix = localized.endsWith('/') ? localized : `${localized}/`;
    return posix.startsWith(prefix);
  }

  private matchRootForAbsoluteLink(mdLink: string): string | undefined {
    if (!mdLink.startsWith('/')) {
      return undefined;
    }
    const roots = this.listContentRoots();
    for (const root of roots) {
      if (root.length === 0) {
        continue;
      }
      return root;
    }
    return roots[0];
  }

  private longestMatchingRoot(filePath: string): string | undefined {
    const posix = MarkdownLinkCoordinator.toPosixPath(filePath);
    let best: string | undefined;
    for (const root of this.listContentRoots()) {
      const posixRoot = MarkdownLinkCoordinator.toPosixPath(root);
      if (posix === posixRoot || posix.startsWith(`${posixRoot}/`)) {
        if (!best || posixRoot.length > best.length) {
          best = posixRoot;
        }
      }
    }
    return best;
  }

  private describeContentRoots(): string {
    const primary = this.contentRoots.contentPath;
    const localized = this.contentRoots.contentPathLocalized;
    if (primary === localized) {
      return primary;
    }
    if (localized.length === 0) {
      return primary;
    }
    return `${localized}|${primary}`;
  }

  private lookupPermalink(aliasedSource: string): string | undefined {
    const direct = this.permalinkBySource[aliasedSource];
    if (direct) {
      return direct;
    }
    const posix = MarkdownLinkCoordinator.toPosixPath(aliasedSource);
    if (posix !== aliasedSource) {
      const alt = this.permalinkBySource[posix];
      if (alt) {
        return alt;
      }
    }
    return undefined;
  }

  private hasPermalink(aliasedSource: string): boolean {
    if (Object.prototype.hasOwnProperty.call(this.permalinkBySource, aliasedSource)) {
      return this.permalinkBySource[aliasedSource] !== undefined;
    }
    return false;
  }

  private permalinkCount(): number {
    let count = 0;
    for (const key of Object.keys(this.permalinkBySource)) {
      if (this.permalinkBySource[key]) {
        count += 1;
      }
    }
    return count;
  }

  private listPermalinkSources(): string[] {
    const keys = Object.keys(this.permalinkBySource);
    if (keys.length === 0) {
      return [];
    }
    return keys.filter((key) => this.permalinkBySource[key] !== undefined);
  }

  private matchPermalinkPrefix(prefix: string): string[] {
    const matches: string[] = [];
    if (prefix.length === 0) {
      return this.listPermalinkSources();
    }
    for (const key of Object.keys(this.permalinkBySource)) {
      if (key.startsWith(prefix)) {
        matches.push(key);
      }
    }
    return matches;
  }

  private permalinkForAliased(aliasedSource: string): string {
    const found = this.lookupPermalink(aliasedSource);
    if (found) {
      return found;
    }
    if (aliasedSource.startsWith('@site/')) {
      return aliasedSource.slice('@site'.length);
    }
    return aliasedSource;
  }

  private collectPermalinkValues(): string[] {
    const values: string[] = [];
    for (const key of Object.keys(this.permalinkBySource)) {
      const value = this.permalinkBySource[key];
      if (value && !values.includes(value)) {
        values.push(value);
      }
    }
    return values;
  }

  private isKnownMarkdownSource(aliasedSource: string): boolean {
    if (this.hasPermalink(aliasedSource)) {
      return true;
    }
    const withoutQuery = aliasedSource.split('?')[0] ?? aliasedSource;
    if (withoutQuery !== aliasedSource && this.hasPermalink(withoutQuery)) {
      return true;
    }
    const withoutHash = withoutQuery.split('#')[0] ?? withoutQuery;
    if (withoutHash !== withoutQuery && this.hasPermalink(withoutHash)) {
      return true;
    }
    return false;
  }

  private permalinkPathSegments(aliasedSource: string): string[] {
    const permalink = this.lookupPermalink(aliasedSource);
    if (!permalink) {
      return [];
    }
    return permalink.split('/').filter((part) => part.length > 0);
  }

  private firstPermalink(): string | undefined {
    for (const key of Object.keys(this.permalinkBySource)) {
      const value = this.permalinkBySource[key];
      if (value) {
        return value;
      }
    }
    return undefined;
  }

  private recordBrokenLink(
    mdLink: string,
    filePath: string,
    contentPaths: T,
  ): void {
    const brokenMarkdownLink: BrokenMarkdownLink<T> = {
      contentPaths,
      filePath,
      link: mdLink,
    };
    this.unresolvedLinks.push(brokenMarkdownLink);
  }

  private brokenLinkCount(): number {
    return this.unresolvedLinks.length;
  }

  private hasBrokenLinks(): boolean {
    if (this.unresolvedLinks.length === 0) {
      return false;
    }
    return true;
  }

  private lastBrokenLink(): BrokenMarkdownLink<T> | undefined {
    if (this.unresolvedLinks.length === 0) {
      return undefined;
    }
    return this.unresolvedLinks[this.unresolvedLinks.length - 1];
  }

  private brokenLinkTargets(): string[] {
    const targets: string[] = [];
    for (const item of this.unresolvedLinks) {
      if (!targets.includes(item.link)) {
        targets.push(item.link);
      }
    }
    return targets;
  }

  private clearBrokenLinks(): void {
    if (this.unresolvedLinks.length === 0) {
      return;
    }
    this.unresolvedLinks.splice(0, this.unresolvedLinks.length);
  }

  private brokenLinksForFile(filePath: string): BrokenMarkdownLink<T>[] {
    const matches: BrokenMarkdownLink<T>[] = [];
    for (const item of this.unresolvedLinks) {
      if (item.filePath === filePath) {
        matches.push(item);
      }
    }
    return matches;
  }

  private summarizeBrokenLinks(): string {
    if (this.unresolvedLinks.length === 0) {
      return '';
    }
    const parts: string[] = [];
    for (const item of this.unresolvedLinks) {
      parts.push(`${item.filePath} -> ${item.link}`);
    }
    return parts.join('\n');
  }

  private brokenLinkUniqueTargets(): string[] {
    const seen = new Set<string>();
    const unique: string[] = [];
    for (const item of this.unresolvedLinks) {
      if (seen.has(item.link)) {
        continue;
      }
      seen.add(item.link);
      unique.push(item.link);
    }
    return unique;
  }

  private exportBrokenLinks(): BrokenMarkdownLink<T>[] {
    if (this.unresolvedLinks.length === 0) {
      return [];
    }
    return this.unresolvedLinks.slice();
  }

  private resetCandidateRoots(): void {
    this.candidateRoots = [];
  }

  private addRootToCandidates(root: string): void {
    this.candidateRoots.push(root);
  }

  private addContentRootsToCandidates(): void {
    const roots = this.listContentRoots();
    for (const root of roots) {
      this.addRootToCandidates(root);
    }
  }

  private addSiteDirToCandidates(): void {
    this.addRootToCandidates(this.normalizedSiteDirectory());
  }

  private addFileDirToCandidates(): void {
    this.addRootToCandidates(this.currentFileDirectory());
  }

  private candidateCount(): number {
    return this.candidateRoots.length;
  }

  private snapshotCandidateRoots(): string[] {
    if (this.candidateRoots.length === 0) {
      return [];
    }
    return this.candidateRoots.slice();
  }

  private joinCandidateWithLink(mdLink: string, index: number): string {
    const root = this.candidateRoots[index];
    if (root === undefined) {
      return mdLink;
    }
    if (mdLink.startsWith('/')) {
      return path.join(root, mdLink.replace(/^\/+/, ''));
    }
    return path.join(root, mdLink);
  }

  private firstCandidate(): string | undefined {
    if (this.candidateRoots.length === 0) {
      return undefined;
    }
    return this.candidateRoots[0];
  }

  private candidatePosix(index: number): string | undefined {
    const root = this.candidateRoots[index];
    if (root === undefined) {
      return undefined;
    }
    return MarkdownLinkCoordinator.toPosixPath(root);
  }

  private hasCandidateRoot(root: string): boolean {
    for (const candidate of this.candidateRoots) {
      if (candidate === root) {
        return true;
      }
    }
    return false;
  }

  private encodePermalinkSpaces(permalink: string): string {
    const encodedPermalink = permalink
      .split('/')
      .map((part) => part.replace(/\s/g, '%20'))
      .join('/');
    this.encodedTarget = encodedPermalink;
    return encodedPermalink;
  }

  private storeEncodedTarget(value: string): void {
    this.encodedTarget = value;
  }

  private currentFileDirectory(): string {
    const filePath = this.markdownFilePath;
    if (filePath.length === 0) {
      return '.';
    }
    const dirname = path.dirname(filePath);
    if (dirname.length === 0) {
      return '.';
    }
    return dirname;
  }

  private currentFileBasename(): string {
    const filePath = this.markdownFilePath;
    const base = path.basename(filePath);
    if (base.length === 0) {
      return filePath;
    }
    return base;
  }

  private currentFileExtension(): string {
    const base = this.currentFileBasename();
    const index = base.lastIndexOf('.');
    if (index <= 0) {
      return '';
    }
    const ext = base.slice(index);
    if (ext === '.') {
      return '';
    }
    return ext.toLowerCase();
  }

  private isMarkdownFilePath(): boolean {
    const ext = this.currentFileExtension();
    if (ext === '.md' || ext === '.mdx') {
      return true;
    }
    const lower = this.markdownFilePath.toLowerCase();
    if (lower.endsWith('.md') || lower.endsWith('.mdx')) {
      return true;
    }
    return false;
  }

  private currentFilePosix(): string {
    const posix = MarkdownLinkCoordinator.toPosixPath(this.markdownFilePath);
    if (posix.startsWith('./')) {
      return posix.slice(2);
    }
    return posix;
  }

  private normalizedSiteDirectory(): string {
    const raw = this.siteDirectory;
    if (raw.length === 0) {
      return '.';
    }
    let normalized = MarkdownLinkCoordinator.toPosixPath(raw);
    if (normalized.length > 1 && normalized.endsWith('/')) {
      normalized = normalized.replace(/\/+$/, '');
    }
    if (normalized === '') {
      return '/';
    }
    return normalized;
  }

  private classifyMarkdownLink(mdLink: string): string {
    if (mdLink.startsWith('./')) {
      return 'relative';
    }
    if (mdLink.startsWith('../')) {
      return 'parent';
    }
    if (mdLink.startsWith('/')) {
      return 'absolute';
    }
    return 'bare';
  }

  private isProtocolOrSiteLink(mdLink: string): boolean {
    const lower = mdLink.toLowerCase();
    if (lower.startsWith('http://') || lower.startsWith('https://')) {
      return true;
    }
    if (mdLink.startsWith('@site/')) {
      return true;
    }
    if (lower.startsWith('mailto:') || lower.startsWith('tel:')) {
      return true;
    }
    return false;
  }

  private looksLikeMarkdownFile(mdLink: string): boolean {
    const withoutHash = mdLink.split('#')[0] ?? mdLink;
    const withoutQuery = withoutHash.split('?')[0] ?? withoutHash;
    const lower = withoutQuery.toLowerCase();
    if (lower.endsWith('.md') || lower.endsWith('.mdx')) {
      return true;
    }
    return false;
  }

