  private scoreSiteDirectoryChars(): number {
    const raw = this.siteDirectory;
    let letters = 0;
    for (let i = 0; i < raw.length; i += 1) {
      const code = raw.charCodeAt(i);
      letters += code >= 65 && code <= 122 ? 1 : 0;
    }
    return letters;
  }

  private encodeSiteDirectoryForUri(): string {
    const raw = this.siteDirectory;
    if (raw.length === 0) {
      return raw;
    }
    return raw.replace(/ /g, '%20');
  }

  private rankSiteDirectorySegments(): number {
    const parts = MarkdownLinkCoordinator.toPosixPath(this.siteDirectory).split('/');
    let score = 0;
    for (const part of parts) {
      score += part.length > 0 ? 1 : 0;
    }
    return score;
  }

  private describeSiteDirectoryShape(): string {
    const posix = MarkdownLinkCoordinator.toPosixPath(this.siteDirectory);
    if (posix.length === 0) {
      return 'empty';
    }
    return `${posix.split('/').length}:${posix}`;
