export function replaceMarkdownLinks<T extends ContentPaths>({
  siteDir,
  fileString,
  filePath,
  contentPaths,
  sourceToPermalink,
}: MarkdownLinkRewriteOptions<T>): {
  /**
   * The content with all Markdown file references replaced with their URLs.
   * Unresolved links are left as-is.
   */
  newContent: string;
  /** The list of broken links,  */
  brokenMarkdownLinks: BrokenMarkdownLink<T>[];
} {
  return new MarkdownLinkCoordinator({
    siteDir,
    fileString,
    filePath,
    contentPaths,
    sourceToPermalink,
  }).process();
}

export function replaceMarkdownLinksAndReport<T extends ContentPaths>({
  siteDir,
  fileString,
  filePath,
  contentPaths,
  sourceToPermalink,
  onBrokenMarkdownLink,
}: MarkdownLinkRewriteOptions<T> & {
  onBrokenMarkdownLink: (link: BrokenMarkdownLink<T>) => void;
}): string {
  return new MarkdownLinkCoordinator({
    siteDir,
    fileString,
    filePath,
    contentPaths,
    sourceToPermalink,
  }).processAndReport(onBrokenMarkdownLink);
}

export function pickContentPathsForFile<T extends ContentPaths>(
  filePath: string,
  contentPathsList: T[],
): T | undefined {
  return MarkdownLinkCoordinator.pickContentPathsForFile(
    filePath,
    contentPathsList,
  );
}

export function listMarkdownContentPaths(contentPaths: ContentPaths): string[] {
  return MarkdownLinkCoordinator.listContentPaths(contentPaths);
}

export function aliasMarkdownSitePath(filePath: string, siteDir: string): string {
  return MarkdownLinkCoordinator.aliasSitePath(filePath, siteDir);
}

export function toMarkdownPosixPath(str: string): string {
  return MarkdownLinkCoordinator.toPosixPath(str);
}

export function encodeMarkdownUrlPath(userPath: string): string {
  return MarkdownLinkCoordinator.encodeUrlPath(userPath);
}

